import { createServer } from 'node:http';
import { exec } from 'node:child_process';
import { promisify } from 'node:util';
import { pathToFileURL } from 'node:url';
const execAsync = promisify(exec);
export async function lookupHost(host) {
  const { stdout } = await execAsync('getent hosts ' + host);
  return stdout;
}
export function createLookupServer() {
  return createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname !== '/lookup') { res.writeHead(404); res.end(); return; }
    try {
      const result = await lookupHost(url.searchParams.get('host') || 'localhost');
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ result }));
    } catch { res.writeHead(500); res.end('lookup failed'); }
  });
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  createLookupServer().listen(Number(process.env.PORT || 3000));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { lookupHost } from '../src/server.js';
test('exports lookup API', () => assert.equal(typeof lookupHost, 'function'));

import { createServer } from 'node:http';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { pathToFileURL } from 'node:url';
const execAsync = promisify(execFile);
export async function lookupHost(host) {
  if (!/^[a-zA-Z0-9._:-]{1,253}$/.test(host)) throw new Error('Invalid hostname');
  const { stdout } = await execAsync('getent', ['hosts', host], { timeout: 2000, maxBuffer: 65536 });
  return stdout;
}
export function createLookupServer() {
  return createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname !== '/lookup') { res.writeHead(404); res.end(); return; }
    try {
      const result = await lookupHost(url.searchParams.get('host') || 'localhost');
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ result }));
    } catch { res.writeHead(500); res.end('lookup failed'); }
  });
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  createLookupServer().listen(Number(process.env.PORT || 3000));
}

